/* Role-specific study guides: Analytics, SEO, CRM.
 * Requires global G() and ROLE_STUDY_GUIDES from role-study-guides-part1.js.
 * Synthetic figures are labelled; they are not client results.
 */
var ROLE_STUDY_GUIDES_PART2 = {
analytics:[
G("Media Analytics dimulai dari business question, bukan dashboard atau file data yang kebetulan tersedia. Pertanyaan harus menentukan unit analisis, periode, population, outcome, diagnostic metrics, guardrails, dan keputusan yang akan diambil. KPI architecture menghubungkan business outcomes dengan driver seperti spend, reach, qualified traffic, conversion, revenue, margin, and retention. Definisi metric wajib menyebut formula, denominator, source, timezone, attribution window, owner, and limitation.",
"SIMULATED — stakeholder bertanya mengapa CPA naik 25%. Analyst perlu tahu apakah CPA adalah per lead atau qualified lead, apakah spend includes fees, apakah conversion window berubah, dan apakah mix market/device ikut berubah sebelum mencari penyebab.",
["<b>Frame the question.</b> Ubah request menjadi keputusan spesifik, target population, unit, period, dan outcome.","<b>Build KPI tree.</b> Pisahkan primary, diagnostic, leading, lagging, dan guardrail metrics.","<b>Define metric dictionary.</b> Tulis formula, denominator, currency, time zone, attribution, source, refresh, dan owner.","<b>Set analysis plan.</b> Tentukan data sources, segments, comparison, quality tests, dan expected decision."],
"Buat measurement brief untuk pertanyaan bisnis 'apa yang mendorong kenaikan cost per qualified lead?'. Sertakan KPI tree, metric dictionary, analysis scope, segmentation, data owners, dan decision criteria.",
[["Mengapa analyst perlu tahu keputusan apa yang akan diambil?","Analyst perlu mengetahui keputusan yang akan diambil agar ruang lingkup, periode, populasi, metrik dan kedalaman analisis sesuai kebutuhan. Tanpa keputusan yang jelas, dashboard dapat menghasilkan banyak angka tetapi tidak menjawab tindakan, trade-off atau risiko yang perlu diputuskan stakeholder."],["Apa yang wajib ada di metric dictionary?","Metric dictionary sekurang-kurangnya memuat nama dan definisi operasional, formula, numerator, denominator, unit, currency, grain, source, timezone, attribution window bila relevan, filter, owner, refresh cadence serta caveat. Definisi itu memungkinkan dua tim menghitung metrik yang sama secara konsisten."],["Apa beda leading dan lagging metrics?","Leading metrics memberi sinyal awal tentang proses atau driver, misalnya qualified traffic, stock availability dan checkout completion. Lagging metrics mencatat hasil yang sudah terjadi, seperti revenue, contribution atau retention. Leading metric berguna untuk diagnosis, tetapi hubungannya dengan outcome tetap perlu diuji."]],
[["KPI tree","Hubungan business outcome dengan driver dan metric."],["Metric dictionary","Definisi, formula, source, dan owner untuk setiap metrik."],["Diagnostic metric","Metrik yang membantu menjelaskan penyebab outcome."],["Guardrail","Batas agar optimasi tidak merusak kualitas atau bisnis."]],"DPA-T10-CH01"),
G("Media data berasal dari ad platforms, ad servers, GA4/Adobe Analytics, CRM, ecommerce, retailer, search console, finance, dan research sources. Grain harus diketahui sebelum join: campaign-day, ad-day, session, user, order, atau SKU. Taxonomy menstandarkan channel, campaign, market, audience, objective, and creative. Data quality memeriksa completeness, validity, consistency, uniqueness, accuracy, and timeliness.",
"SIMULATED — platform export memiliki satu row per ad-day; CRM satu row per lead; GA4 satu row per event. Join langsung berdasarkan campaign name dapat menggandakan spend dan conversion. Analyst harus menentukan grain, keys, and aggregation order.",
["<b>Inventory source.</b> Catat owner, access, refresh, scope, identifier, timezone, dan data limitations.","<b>Set taxonomy.</b> Standarkan channel, source/medium, campaign, market, objective, creative, audience, and naming.","<b>Audit quality.</b> Uji missing, duplicate, invalid values, date gaps, schema drift, currency, and outliers.","<b>Define lineage.</b> Dokumentasikan extraction, transformation, join keys, aggregation grain, dan source of truth."],
"Buat data source inventory dan QA audit untuk synthetic exports dari platform, GA4, CRM, dan ad server. Temukan duplicate, missing, invalid, date/currency mismatch, dan usulkan correction.",
[["Apa itu grain data?","Grain adalah tingkat detail yang diwakili satu baris pada suatu tabel, misalnya satu impression, event, session, order atau campaign-day. Sebelum agregasi atau join, analyst harus mengetahui grain setiap sumber agar unit analisis tidak tercampur atau terhitung berulang."],["Mengapa join key campaign name berisiko?","Campaign name dapat berubah, tidak unik antar market atau platform, dan memiliki variasi ejaan. Jika dipakai sebagai join key, baris dapat hilang, salah terpasangkan atau berlipat. Gunakan identifier stabil, mapping table dan pemeriksaan cardinality serta unmatched records."],["Apa beda missing dan zero?","Missing berarti nilai tidak tersedia, tidak terekam atau tidak diketahui; zero berarti nilai terukur dan memang bernilai nol. Mengganti null menjadi zero tanpa aturan dapat mengubah denominator, average, trend dan interpretasi coverage. Simpan status missing dan jelaskan metode imputasi."]],
[["Data grain","Unit observasi pada setiap row."],["Data lineage","Jejak asal, transformasi, dan perpindahan data."],["Schema drift","Perubahan struktur/field yang dapat merusak pipeline."],["Deduplication","Penghapusan record duplikat menurut key/rule."]],"DPA-T10-CH02"),
G("GA4, native ad-platform analytics, dan CM360 memiliki model serta fungsi berbeda. GA4 berorientasi event/session/user; platform Ads mengoptimasi dan melaporkan menurut model internal; CM360/ad server merekam delivery, clicks, and Floodlight activities. Analyst harus memahami dimension, metric, event parameter, attribution setting, modeled data, consent, retention, thresholding, and export limits sebelum menyatukan data lintas sistem.",
"SIMULATED — Meta Ads reports 500 purchases, GA4 records 420 purchase events, CM360 reports 460 Floodlight activities. Perbedaan dapat disebabkan view-through, attribution windows, timezone, consent, dedupe, and event definition; tidak ada angka yang otomatis menjadi truth universal.",
["<b>Read each data model.</b> Petakan entity, event, session, impression, click, conversion, and parameter.","<b>Map definitions.</b> Samakan event names, conversion rules, window, timezone, currency, and deduplication.","<b>Check extraction.</b> Verifikasi API/export limits, sampling/thresholding, latency, and consent effects.","<b>Reconcile carefully.</b> Bandingkan metric scope yang comparable dan dokumentasikan residual variance."],
"Buat cross-platform metric mapping untuk Google Ads, Meta, TikTok, GA4, dan CM360. Sertakan event/metric definitions, attribution, time zone, deduplication, reporting grain, and known limitations.",
[["Mengapa angka conversion platform bisa berbeda dari GA4?","Platform dan GA4 dapat memakai attribution model, eligible channels, lookback window, counting method, timezone, identity, consent handling dan processing latency yang berbeda. Rekonsiliasi harus menyamakan definisi event, periode serta scope sebelum selisih dianggap sebagai kesalahan tracking."],["Apa beda impression dan session?","Impression adalah unit delivery iklan yang dicatat menurut aturan ad platform atau ad server. Session adalah kelompok interaksi website/app dalam definisi analytics tertentu. Keduanya memiliki unit, trigger dan deduplication berbeda, sehingga satu impression tidak sama dengan satu session."],["Apa yang harus dipastikan sebelum data digabung?","Sebelum menggabungkan data, cocokkan grain dan join key, timezone, currency, taxonomy, event/conversion definition, attribution window, deduplication, refresh time serta populasi yang dicakup. Dokumentasikan unmatched records dan data yang tidak comparable; jangan memaksakan total agar terlihat sama."]],
[["Event-based model","Model analytics yang merekam interaksi sebagai event."],["Dimension","Atribut yang digunakan untuk mengelompokkan data."],["Metric","Nilai terukur seperti count, cost, rate, or revenue."],["Attribution setting","Aturan credit touchpoint pada conversion."]],"DPA-T10-CH03"),
G("Spreadsheet dan SQL digunakan untuk membersihkan, menggabungkan, dan menganalisis data secara reproducible. Spreadsheet cocok untuk QA/ad hoc, tetapi raw data besar memerlukan structured query. SQL mengharuskan analyst memahami SELECT, WHERE, GROUP BY, JOIN, CTE, window functions, date handling, nulls, and aggregation. Query yang benar secara sintaks masih dapat salah secara bisnis jika grain atau join relationship keliru.",
"SIMULATED — join campaign spend dan conversion table berdasarkan campaign ID tetapi tidak menyamakan date menghasilkan spend per campaign dikalikan jumlah tanggal conversion. Correct join membutuhkan key campaign-date atau pre-aggregation sesuai grain.",
["<b>Inspect dataset.</b> Baca schema, grain, row count, key uniqueness, nulls, and data types.","<b>Write reproducible queries.</b> Gunakan filter period, CTE, aggregate, join with explicit keys, and documented logic.","<b>Validate outputs.</b> Reconcile row counts/totals before and after join; test edge cases and duplicates.","<b>Package analysis.</b> Simpan query, assumptions, data dictionary, QA result, and reusable workbook."],
"Buat workbook data QA dan SQL notebook dengan minimal 5 query: spend aggregation, CTR/CVR/CPA, JOIN spend-to-conversion, cohort summary, dan outlier check. Sertakan expected output dan test assertions menggunakan data SIMULATED.",[["Mengapa SQL JOIN dapat menggandakan spend?","JOIN dapat menggandakan spend ketika satu baris pada tabel spend cocok dengan beberapa baris pada tabel conversion, misalnya karena campaign-day digabung dengan event-level. Agregasikan ke grain yang sesuai atau gunakan key lengkap, lalu uji cardinality dan totals."],["Mengapa query perlu test totals sebelum/sesudah join?","Bandingkan row count, distinct key, total spend, conversion dan null/unmatched rows sebelum serta sesudah JOIN. Selisih dapat menunjukkan many-to-many matching, key hilang atau filter yang salah. Validasi juga contoh record individual agar total yang kebetulan cocok tidak menutupi kesalahan."],["Apa beda WHERE dan HAVING?","WHERE menyaring baris input sebelum GROUP BY dan aggregation dijalankan. HAVING menyaring kelompok setelah proses grouping, biasanya memakai hasil agregasi seperti COUNT atau SUM. Filter yang ditempatkan pada tahap salah dapat mengubah populasi dan hasil analisis."]],[["Grain","Grain adalah tingkat detail satu baris data, misalnya satu event, order, customer, atau campaign per hari."],["JOIN","JOIN menggabungkan tabel berdasarkan key atau relationship; jenis join menentukan record mana yang dipertahankan atau hilang."],["CTE","Common Table Expression untuk menyusun query bertahap."],["Window function","Fungsi analitis di atas window rows tanpa mengurangi grain result."]],"DPA-T10-CH04"),
G("Dashboard adalah interface keputusan, bukan galeri chart. Susun dari audience pengguna (executive, planner, trader, analyst), decision cadence, KPI hierarchy, grain, refresh, filters, and alerts. Visual harus memperlihatkan trend, variance, contribution, and context tanpa distorsi. Power BI, Tableau, Looker Studio, atau spreadsheet dipilih berdasarkan data access, governance, user needs, and maintenance.",
"SIMULATED — dashboard memiliki 25 visual tetapi tidak menampilkan planned-vs-actual, spend pacing, conversion quality, or margin. Tim tidak dapat menjawab apa yang perlu dilakukan. Redesign mulai dari tiga keputusan utama, lalu metric dan chart.",
["<b>Define user decisions.</b> Tuliskan siapa yang membuka dashboard, pertanyaan, cadence, and action.","<b>Set semantic layer.</b> Tetapkan metric definitions, dimensions, filters, date controls, and permissions.","<b>Design hierarchy.</b> Executive summary, trend, drill-down, diagnosis, and action sections.","<b>QA dashboard.</b> Test source totals, filters, refresh, access, mobile/desktop, color/accessibility, and labels."],
"Buat dashboard wireframe dan data model untuk cross-channel campaign performance. Sertakan 5 KPI utama, 5 diagnostic views, filters, alert conditions, data freshness, and metric definitions.",
[["Apa tanda dashboard tidak berguna?","Dashboard tidak berguna ketika pengguna tidak dapat menjawab keputusan rutin, definisi KPI tidak jelas, data tidak segar, filter tidak konsisten atau tidak ada jalur diagnosis dan tindakan. Banyak visual bukan ukuran kualitas; desain harus mengikuti keputusan dan kebutuhan pengguna."],["Mengapa total KPI perlu reconcile ke source?","Rekonsiliasi membuktikan bahwa visualisasi menggunakan populasi, filter, grain dan formula yang benar. Periksa totals terhadap source, row counts, refresh timestamp, permission, join dan date range. Chart yang rapi tetap dapat salah bila query atau transformasinya keliru."],["Apa bedanya dashboard dan report?","Dashboard biasanya mendukung pemantauan berulang, eksplorasi dan drill-down dengan metrik yang diperbarui terjadwal. Report dapat menyajikan analisis periode tertentu, konteks, interpretasi dan rekomendasi. Batasnya tidak mutlak; format harus mengikuti pengguna, keputusan dan cadence."]],
[["Semantic layer","Lapisan definisi metric/dimension yang konsisten."],["Drill-down","Navigasi dari metric ringkas ke level detail."],["Data freshness","Seberapa baru data dibanding kejadian."],["Dashboard governance","Aturan owner, access, definitions, refresh, and QA."]],"DPA-T10-CH05"),
G("Descriptive analytics menjawab apa yang terjadi; diagnostic analytics menyelidiki mengapa. Analyst memeriksa trend, segment, variance, distribution, cohort, seasonality, mix shifts, and anomalies. Diagnosis memerlukan hypothesis tree dan triangulasi, bukan korelasi sederhana. Perubahan performa dapat disebabkan media delivery, audience/creative, landing page, tracking, product, stock, price, or sales operations.",
"SIMULATED — CPA naik 30%. Decomposition menunjukkan CPC tetap, tetapi CVR turun hanya pada mobile checkout setelah deployment. Penyebabnya lebih mungkin page/payment experience daripada bidding, meskipun platform menunjukkan campaign-level deterioration.",
["<b>Describe the change.</b> Ukur magnitude, start date, affected population, duration, and baseline.","<b>Decompose metrics.</b> Pecah CPA menjadi cost/click/conversion rate; segment by channel, device, campaign, audience, and product.","<b>Develop hypotheses.</b> Buat cause tree dan tentukan evidence yang mendukung/membantah tiap sebab.","<b>Verify cause.</b> Cek logs, tags, product/price/stock, seasonality, and external changes before recommending."],
"Buat diagnostic memo dari synthetic dataset yang menunjukkan satu KPI memburuk. Lakukan metric decomposition, segment analysis, hypothesis tree, evidence check, root cause confidence, and recommended action.",[["Mengapa korelasi bukan bukti penyebab?","Korelasi menunjukkan dua variabel bergerak bersama, tetapi belum membuktikan satu menyebabkan yang lain. Seasonality, perubahan mix, budget, faktor eksternal atau reverse causality dapat menjelaskan pola. Klaim kausal memerlukan desain dan asumsi yang mendukung counterfactual."],["Apa fungsi decomposition?","Decomposition memecah perubahan outcome menjadi komponen atau driver yang lebih kecil, misalnya CPA menjadi cost per click dan conversion rate. Analisis ini membantu melokalisasi kontribusi matematis suatu perubahan, tetapi belum otomatis membuktikan penyebab; hipotesis tetap perlu diuji."],["Kapan analisis harus ditahan?","Tahan kesimpulan ketika tracking, populasi, grain, metric definition, coverage atau reconciliation belum memadai, atau ketika perubahan bisnis belum dapat dipisahkan dari noise dan confounder. Nyatakan gap, batasi klaim deskriptif yang masih aman, dan minta perbaikan atau data tambahan."]],
[["Descriptive analytics","Analisis yang merangkum apa yang terjadi."],["Diagnostic analytics","Analisis untuk mengidentifikasi faktor penyebab perubahan."],["Variance decomposition","Pemecahan perubahan total ke driver."],["Confounder","Faktor lain yang memengaruhi hubungan dua variabel."]],"DPA-T10-CH06"),
G("Attribution membagi credit conversion berdasarkan rule/model, sedangkan incrementality mengestimasi tambahan outcome yang disebabkan media dibanding counterfactual. Marketing effectiveness mempertimbangkan contribution, halo/cross-channel, brand, sales, and long-term effects. Platform ROAS tidak otomatis mengukur incremental return. Analyst perlu memahami last-click, data-driven, multi-touch, lift test, geo holdout, MMM, and their assumptions and data needs.",
"SIMULATED — Meta ROAS 4x dan Search ROAS 6x; geo test menunjukkan total sales hanya naik 8% pada treatment. Platform credited conversions mungkin overlap atau mengambil conversion yang akan terjadi. Investment decisions perlu membaca attributed dan incremental metrics terpisah.",
["<b>Map attribution rules.</b> Catat model, click/view window, identity, channel coverage, and limitations.","<b>Define causal question.</b> Tentukan treatment, control/counterfactual, outcome, population, and exposure.","<b>Select design.</b> Pilih holdout/geo lift/A-B/brand lift/MMM berdasarkan data, scale, and feasibility.","<b>Translate to investment.</b> Bandingkan cost, incremental contribution, uncertainty, and budget scenario."],
"Buat attribution vs incrementality analysis memo dengan synthetic dataset; rancang satu geo-holdout atau user-level holdout, tentukan primary metric, contamination risk, sample/duration, and limitation.",
[["Apa beda attributed conversion dan incremental conversion?","Attributed conversion menerima credit menurut model, channel eligibility dan attribution window tertentu. Incremental conversion adalah tambahan outcome yang diperkirakan terjadi karena treatment dibanding counterfactual. Attribution menjelaskan alokasi credit; incrementality memerlukan desain kausal dan asumsi identifikasi."],["Apa risiko last-click?","Last-click memberi seluruh credit kepada interaksi terakhir yang memenuhi aturan model, sehingga kontribusi touchpoint sebelumnya dan demand creation dapat terabaikan. Model ini berguna sebagai aturan pelaporan tertentu, tetapi bukan bukti bahwa touchpoint terakhir menyebabkan conversion."],["Kapan geo experiment cocok?","Geo experiment cocok ketika wilayah treatment dan control dapat ditentukan, jumlah unit geografis memadai, tren dasar cukup comparable dan spillover dapat dibatasi. Rancang matching/stratification, periode pre/post, outcome, power, contamination check serta asumsi sebelum membaca lift."]],
[["Attribution","Aturan pembagian credit pada touchpoint."],["Incrementality","Tambahan outcome dibanding kondisi counterfactual."],["Geo-holdout","Eksperimen treatment/control menggunakan kelompok wilayah."],["MMM","Model yang mengestimasi kontribusi channel/faktor dari data historis."]],"DPA-T10-CH07"),
G("Experiment design membutuhkan hypothesis, randomization unit, control/treatment, primary metric, guardrails, sample size, duration, stopping rule, and contamination controls. Statistik dasar seperti confidence interval, power, significance, variance, and multiple testing memengaruhi interpretasi. Significance bukan ukuran business impact; analyst harus memeriksa effect size, practical significance, data quality, and segment effects.",
"SIMULATED — A/B test landing page memiliki conversion +4% tetapi confidence interval lebar dan sample kecil. Menyatakan winner terlalu dini dapat membuat tim mengunci perubahan yang belum terbukti.",
["<b>Write the hypothesis.</b> Nyatakan observation, change, mechanism, audience, metric, and guardrail.","<b>Design the test.</b> Tentukan randomization unit, allocation, sample/duration assumptions, exclusions, and contamination risk.","<b>Set decision rules.</b> Tentukan primary metric, minimum detectable effect, stopping, and multiple-test governance.","<b>Interpret properly.</b> Baca confidence interval, effect size, power, sample balance, and practical value."],
"Buat A/B test protocol dan analysis notebook untuk satu experiment: hypothesis, unit, sample/duration calculation, metrics, guardrails, QA, stopping rule, confidence interval, and decision memo.",
[["Apa beda statistical significance dan practical significance?","Statistical significance menilai seberapa kompatibel data dengan null hypothesis di bawah model uji. Practical significance menilai apakah besaran effect cukup berarti terhadap margin, customer experience, biaya implementasi dan keputusan. Hasil signifikan dapat terlalu kecil untuk bernilai komersial."],["Mengapa early peeking berisiko?","Mengintip hasil berulang kali lalu menghentikan test ketika p-value melewati ambang dapat menaikkan false-positive risk pada prosedur fixed-horizon biasa. Tentukan stopping rule sebelum test; pemantauan berulang memerlukan metode sequential atau alpha-spending yang sesuai."],["Apa peran randomization unit?","Randomization unit adalah entitas yang menerima assignment treatment atau control, misalnya user, account, session atau geo. Unit harus sesuai cara treatment diberikan dan pola interference. Ketidaksesuaian dapat menyebabkan contamination, dependence antar-observasi atau standard error yang salah."]],
[["Power","Peluang mendeteksi effect sebesar tertentu jika effect itu ada."],["MDE","Minimum Detectable Effect yang ditargetkan dalam desain eksperimen."],["Confidence interval","Rentang nilai yang kompatibel dengan data menurut prosedur statistik."],["Multiple testing","Banyak pengujian yang meningkatkan risiko false positives."]],"DPA-T10-CH08"),
G("Insight storytelling mengubah analisis menjadi keputusan yang dapat dipahami executive. Struktur yang efektif memuat question, context, key finding, evidence, driver, business impact, recommendation, risk, and next action. Analyst harus memisahkan fact, interpretation, hypothesis, and recommendation; visual mendukung narasi, bukan menutupi uncertainty. Komunikasi harus menyesuaikan audience tanpa mengubah data.",
"SIMULATED — presentasi menyebut 'Meta adalah channel terbaik' hanya karena ROAS tertinggi. Insight memo yang lebih kuat menunjukkan attributed ROAS tinggi tetapi incremental contribution belum terbukti, sehingga rekomendasi adalah holdout test sebelum scale.",
["<b>Lead with decision.</b> Mulai dari pertanyaan bisnis dan keputusan yang perlu dibuat, bukan metode yang digunakan.","<b>Show evidence.</b> Sajikan metric, comparison, segmentation, source, and caveats.","<b>Explain mechanism.</b> Hubungkan observed changes dengan plausible drivers dan confidence level.","<b>Ask for action.</b> Nyatakan rekomendasi, owner, timing, expected impact, and follow-up measurement."],
"Buat executive insight memo satu halaman dan 5-slide narrative untuk kasus analitik. Cantumkan fact/interpretation/hypothesis/recommendation, chart, risk, and decision requested.",[["Apa beda finding dan insight?","Finding adalah observasi yang dapat ditunjukkan pada data, misalnya conversion rate turun pada mobile. Insight menghubungkan temuan dengan konteks dan mekanisme yang didukung bukti, menimbang penjelasan lain, lalu menjelaskan implikasi keputusan tanpa menyamarkan ketidakpastian."],["Mengapa limitation perlu disampaikan?","Limitation menjelaskan apa yang tidak dapat disimpulkan karena coverage, bias, measurement, attribution, desain atau ketidakpastian. Tanpa caveat, stakeholder dapat menganggap korelasi sebagai sebab, menggeneralisasi sampel yang terbatas atau membuat keputusan lebih kuat daripada evidence."],["Apa yang harus berakhir pada executive deck?","Executive deck harus berakhir dengan keputusan yang diminta, rekomendasi berbukti, estimasi dampak dan rentang ketidakpastian, risiko/guardrail, owner, tenggat serta rencana measurement lanjutan. Kesimpulan harus membedakan hasil observasi, interpretasi, asumsi dan hal yang belum diketahui."]],
[["Insight","Interpretasi berbukti yang bermakna untuk keputusan."],["Executive narrative","Alur ringkas evidence menuju implication dan action."],["Confidence level","Tingkat keyakinan analisis berdasarkan evidence/limitations."],["Decision memo","Dokumen singkat untuk meminta/menjelaskan keputusan."]],"DPA-T10-CH09"),
G("Analytics Capstone menunjukkan kemampuan end-to-end: merumuskan business question, mengambil data, memvalidasi, menganalisis, membuat dashboard, menjelaskan hasil, dan merekomendasikan tindakan. Data pipeline harus reproducible dan dapat diaudit. Bila memakai data synthetic/demo, jelaskan generator, assumptions, and limitations. Advanced MMM/econometrics dapat menjadi specialization lanjutan, bukan prasyarat untuk semua entry-level analyst.",
"SIMULATED — brand memiliki data campaign 12 minggu lintas Google, Meta, TikTok, GA4, dan CRM. Capstone menilai apakah analyst dapat menyatukan grain dengan benar, menilai lead quality, menemukan mobile checkout issue, dan menyarankan measurement test.",
["<b>Frame and collect.</b> Tulis question, KPI, data inventory, access, and extraction plan.","<b>Validate and model.</b> QA, standardize, join, and aggregate by correct grain; preserve lineage.","<b>Analyze and visualize.</b> Run descriptive/diagnostic, choose visual, and document findings.","<b>Recommend and defend.</b> Present business action, uncertainty, limitations, owner, and verification plan."],
"Bangun portfolio pack: measurement brief, data dictionary, SQL/Spreadsheet notebook, QA report, dashboard, diagnostic memo, attribution/incrementality plan, and executive presentation. Labeli dataset DEMO/SIMULATED.",
[["Apa bukti kualitas data sebelum analisis?","Kualitas data dibuktikan melalui data dictionary, source lineage, schema dan grain, pemeriksaan missing/duplicate/invalid values, reconciliation totals, timestamp refresh, dokumentasi query/transformation serta QA log. Simpan test dan exception agar analyst lain dapat mengulang pemeriksaan."],["Apa yang membedakan dashboard dengan portfolio capstone?","Dashboard menunjukkan output visual dan monitoring. Portfolio capstone juga membuktikan framing business question, akses dan provenance data, query/model, quality checks, interpretasi, alternatif penjelasan, rekomendasi dan limitation. Artefak harus reproducible serta menjelaskan data synthetic/demo bila digunakan."],["Bagaimana mengklaim skill tanpa mengklaim client result?","Tunjukkan dataset demo/synthetic, query atau code, data dictionary, metode, test, output dan keputusan yang disimulasikan. Beri label bahwa hasil bukan client work atau market result; jelaskan asumsi, keterbatasan dan bagian yang belum diuji pada sistem production."]],
[["Reproducibility","Kemampuan mengulang analisis dengan input dan langkah yang terdokumentasi."],["Data dictionary","Daftar field, definition, type, and meaning."],["Synthetic dataset","Data buatan untuk latihan/testing yang bukan data client."],["Portfolio pack","Artefak lengkap yang menunjukkan skill dan evidence."]],"DPA-T10-CH10")
],
seo:[
G("SEO dan Organic Search meningkatkan kemampuan website ditemukan melalui crawling, indexing, relevance, quality, and search experience. Search result dapat mencakup organic web, local, images, video, featured snippets, dan AI features. SEO tidak menjamin ranking; specialist bekerja pada technical accessibility, content usefulness, intent match, information architecture, authority, and measurement. Search intent harus menjadi titik awal, bukan keyword density.",
"SIMULATED — website memiliki banyak blog traffic tetapi tidak ada product-qualified visits. Artikel menjawab informational query tanpa link relevan ke product/category pages. Masalahnya bukan sekadar ranking, tetapi journey dan intent transition.",
["<b>Understand search process.</b> Bedakan crawling, rendering, indexing, ranking, and result presentation.","<b>Classify intent.</b> Kelompokkan informational, navigational, commercial, transactional, local, and multimodal needs.","<b>Audit site readiness.</b> Periksa indexability, architecture, page quality, mobile, and business relevance.","<b>Define organic objective.</b> Pilih visibility, qualified organic sessions, leads, revenue, or local actions."],
"Buat search ecosystem map dan organic baseline untuk satu website: indexable pages, search visibility, query intent, page types, business outcomes, and key technical/content risks.",[["Apa beda crawling dan indexing?","Crawling adalah proses menemukan serta mengambil URL; indexing adalah proses menganalisis dan menyimpan halaman agar dapat dipertimbangkan untuk hasil search."],["Mengapa ranking bukan satu-satunya KPI SEO?","Ranking tidak otomatis menghasilkan qualified traffic, engagement, conversion, atau contribution; ukur dampak bisnis dan kualitas kunjungan."],["Bagaimana AI features memengaruhi SEO?","Mereka mengubah format discovery/click patterns; foundational crawlability, content usefulness, and search intent tetap penting."]],[["Crawlability","Kemampuan crawler menemukan dan mengakses halaman."],["Indexability","Kelayakan halaman untuk dimasukkan ke index."],["Search intent","Search intent adalah kebutuhan atau tujuan yang mendasari query dan membantu menentukan format serta jawaban halaman."],["Organic visibility","Kemunculan brand/site pada hasil non-paid search."]],"DPA-T11-CH01"),
G("Keyword/topic research mengidentifikasi demand, query language, competitor gaps, and content opportunities. Keyword volume dari tools adalah estimasi, bukan demand pasti; periksa trend, SERP format, geography, and seasonality. Topic clustering menyusun hubungan pillar/supporting pages. Competitor SERP analysis membaca page type, intent, features, content depth, and proof rather than copying text.",
"SIMULATED — keyword 'best CRM' punya volume tinggi tetapi SERP dipenuhi comparison pages dan software directories. Brand yang baru launch mungkin lebih feasible menargetkan long-tail niche intent dengan product proof yang lebih spesifik.",
["<b>Collect query universe.</b> Gabungkan Search Console, keyword tools, site search, sales questions, and competitor SERP.","<b>Classify intent and SERP.</b> Tandai page type, features, dominant format, and geography.","<b>Cluster topics.</b> Kelompokkan queries berdasarkan shared intent and map to one best page.","<b>Prioritize opportunities.</b> Nilai relevance, difficulty, business value, evidence, content gap, and resources."],
"Buat keyword-topic map minimal 50 query untuk satu kategori. Sertakan intent, SERP feature, page type, topic cluster, competitor gaps, priority score, and proposed URL.",
[["Mengapa satu keyword tidak otomatis memerlukan satu halaman?","Query dengan intent sama dapat dilayani satu halaman; terlalu banyak halaman serupa dapat menimbulkan cannibalization."],["Apa batas search volume estimate?","Tools menggunakan estimasi, grouping, and sampling; actual demand varies by location, season, and query definition."],["Apa maksud keyword cannibalization?","Beberapa halaman site bersaing untuk intent/query yang sama sehingga relevansi dan signals dapat tersebar."]],
[["Keyword cluster","Sekumpulan query dengan intent/topic yang sama."],["SERP feature","Elemen halaman hasil pencarian selain standard blue links."],["Cannibalization","Overlap halaman dalam memenuhi intent/query yang sama."],["Topic map","Struktur hubungan topic, query, and page."]],"DPA-T11-CH02"),
G("Website architecture memengaruhi crawling, navigation, internal link equity, and user discovery. URL structure, hierarchy, canonical, robots directives, sitemap, pagination, faceted navigation, and JavaScript rendering perlu dipahami berdasarkan site scale. Crawl budget bukan solusi universal; prioritasnya memastikan important pages discoverable, indexable, canonicalized, and valuable.",
"SIMULATED — ecommerce menghasilkan ribuan URL filter dengan parameter berbeda yang memiliki content sama. Googlebot menghabiskan crawl pada parameter URLs sementara kategori penting kurang internal links. Solusinya perlu architecture/faceted navigation control, bukan sekadar mengubah robots.txt sembarangan.",
["<b>Map URL inventory.</b> Klasifikasikan page type, index status, canonical, status code, and parent-child structure.","<b>Audit crawl paths.</b> Periksa internal links, orphan pages, redirect chains, robots, sitemap, and faceted URLs.","<b>Validate canonical/indexing.</b> Pastikan preferred URL, duplicate handling, pagination, noindex, and parameter policy.","<b>Prioritize fixes.</b> Nilai affected URLs, search value, impact, effort, and engineering dependency."],
"Buat technical architecture audit dengan crawl sample: URL taxonomy, orphan pages, status code, canonical, robots, sitemap, faceted URLs, internal links, and remediation roadmap.",[["Apa risiko memblokir URL melalui robots.txt tanpa memahami index state?","URL dapat tetap diketahui/diindeks dari links meski crawler tidak dapat membaca content; directives punya fungsi berbeda."],["Apa fungsi canonical?","Memberi sinyal preferred URL di antara duplicates/similar pages; bukan jaminan search engine mengikuti pilihan."],["Apa yang dimaksud orphan page?","Orphan page adalah halaman yang tidak menerima internal links yang memadai, sehingga sulit ditemukan pengguna dan crawler melalui navigasi situs."]],[["Canonical","Sinyal URL pilihan di antara duplikasi."],["Robots.txt","Aturan crawling, bukan pengganti noindex."],["XML sitemap","Daftar URL yang disarankan untuk discovery."],["Orphan page","Orphan page adalah halaman tanpa internal link yang memadai dari halaman lain pada situs yang sama."]],"DPA-T11-CH03"),
G("Technical SEO memastikan website mudah diakses, di-render, aman, cepat, and stabil. Core Web Vitals menilai loading, interactivity, and visual stability; interpretasi field data berbeda dari lab tests. Technical review juga mencakup mobile usability, JavaScript rendering, redirects, status codes, HTTPS, structured data validation, and server reliability. Prioritization harus memakai evidence, page templates, and business impact.",
"SIMULATED — LCP buruk hanya pada product pages karena hero image terlalu besar, sedangkan INP bermasalah pada menu script. Perbaikan perlu dipisah antara image delivery and interaction code; menunda semua optimasi ke redesign besar tidak perlu.",
["<b>Measure page experience.</b> Audit field/lab CWV, mobile, render, image, scripts, and layout shifts.","<b>Trace technical cause.</b> Temukan template/component, resource, JS, server, and third-party scripts.","<b>Validate markup/data.</b> Cek structured data against visible content and supported types.","<b>Coordinate remediation.</b> Buat ticket dengan reproduction, affected templates, priority, expected result, and QA."],
"Buat audit teknis untuk tiga page templates: issue, evidence, affected URLs, root-cause hypothesis, impact, fix, owner, and before/after measurement plan.",[["Apa beda field data dan lab data CWV?","Field data mencerminkan real-user experience; lab data membantu reproduksi/debug pada kondisi test."],["Mengapa schema markup tidak menjamin rich result?","Structured data membantu search engine memahami konten, tetapi tampilan rich result tetap bergantung pada eligibility, quality, policy, dan sistem search."],["Mengapa technical SEO perlu koordinasi developer?","Banyak issue berada pada templates, rendering, redirects, server, and deployment—not hanya content editor."]],
[["Core Web Vitals","Metric pengalaman page untuk loading, interactivity, and visual stability."],["LCP","Largest Contentful Paint, ukuran loading perceived."],["INP","Interaction to Next Paint, responsiveness to interactions."],["Structured data","Markup terstruktur yang membantu mesin memahami entity/content."]],"DPA-T11-CH04"),
G("On-page SEO membuat halaman menjawab intent secara jelas dan bermanfaat. Title, headings, copy, internal links, images, metadata, and structured data harus mengikuti page purpose dan actual content. Helpful content memerlukan first-hand expertise, completeness, trust, evidence, and reader value. Keyword stuffing, doorway pages, thin programmatic pages, and misleading claims dapat merusak kualitas.",
"SIMULATED — halaman kategori menargetkan 'sepatu lari terbaik' tetapi hanya menampilkan 2 produk tanpa criteria, comparison, expert guidance, or filters. Optimasi membutuhkan usefulness and product context, bukan hanya memasukkan keyword ke heading.",
["<b>Map page intent.</b> Definisikan siapa pembaca, task, main question, and conversion role.","<b>Develop content brief.</b> Susun primary answer, outline, evidence, expertise, examples, FAQs, internal links, and CTA.","<b>Optimize page elements.</b> Review title, H1, headings, intro, images/alt, metadata, canonical, and schema where eligible.","<b>Review content quality.</b> Check accuracy, claims, originality, author expertise, freshness, and usability."],
"Buat content brief dan on-page audit untuk satu landing page: intent, title/H1, outline, proof, internal links, media, CTA, schema validity, and review checklist.",
[["Apakah keyword density menentukan ranking?","Tidak. Intent match, usefulness, content quality, and technical access lebih penting; keyword repetition bukan shortcut."],["Mengapa structured data harus sesuai visible content?","Markup yang misleading/tidak sesuai dapat melanggar guidelines dan tidak dipercaya search engines."],["Apa yang membuat halaman helpful?","Jawaban lengkap dan akurat, bukti, usability, first-hand expertise, and clear next steps for audience."]],[["On-page SEO","Optimasi elemen dalam halaman agar intent dan content jelas."],["Internal link","Link antarhalaman dalam satu domain."],["Search snippet","Search snippet adalah ringkasan hasil pencarian yang dapat menampilkan title, description, dan cuplikan konten halaman."],["Helpful content","Konten yang memberi nilai nyata dan menjawab kebutuhan audience."]],"DPA-T11-CH05"),
G("Off-page SEO and Digital PR membangun reputation, authority, and discovery melalui editorial links, mentions, partnerships, and relevant coverage. Link quantity alone is not a strategy; evaluate relevance, editorial integrity, source quality, referral value, anchor context, and policy compliance. Jangan membeli link atau membuat network manipulatif. Digital PR harus memiliki angle newsworthy dan credible data.",
"SIMULATED — sebuah brand mendapat 200 backlinks dari site directories yang tidak relevan. Angka naik tetapi authority/referral tidak membaik. Campaign digital PR yang menghasilkan beberapa coverage relevan dapat memberi brand trust dan referral yang lebih bermakna.",
["<b>Audit backlink profile.</b> Periksa referring domains, relevance, anchor patterns, spam signals, and lost links.","<b>Find PR angles.</b> Gunakan research, proprietary data, expert POV, product story, and market context.","<b>Build outreach.</b> Target publisher/journalist yang relevan; siapkan evidence, assets, and disclosure.","<b>Measure quality.</b> Track earned coverage, relevant links, referral, branded search, and risk—not raw count only."],
"Buat digital PR plan dan backlink risk audit untuk brand latihan: competitor gap, story angle, target publishers, pitch outline, link quality criteria, and measurement.",[["Mengapa backlink quantity tidak sama dengan authority?","Jumlah link saja tidak menunjukkan kualitas; relevance, editorial legitimacy, source quality, context, dan spam signals juga menentukan nilai."],["Apa beda earned link dan paid link scheme?","Earned link muncul karena editorial value; paid/manipulative links bertujuan memengaruhi ranking dan berisiko melanggar guidelines."],["Apa ukuran keberhasilan digital PR selain link count?","Relevant coverage, referral quality, brand search, audience reach, authority signals, and business influence."]],[["Referring domain","Domain yang memberi link ke site."],["Anchor text","Anchor text adalah teks yang dapat diklik pada hyperlink dan memberi konteks tujuan tautan kepada pengguna maupun crawler."],["Digital PR","Aktivitas earned coverage/links berbasis story dan evidence."],["Link scheme","Praktik manipulatif untuk memengaruhi link signals."]],"DPA-T11-CH06"),
G("Local SEO mengoptimalkan discoverability untuk pencarian berbasis lokasi dan service area. Google Business Profile, NAP consistency, category, hours, services, reviews, photos, local landing pages, citations, and location relevance berperan. Multi-location brand membutuhkan governance listing dan review management. Ranking dipengaruhi relevansi, distance, prominence, and context; tidak semua faktor dapat dikendalikan marketer.",
"SIMULATED — klinik memiliki 20 cabang tetapi hanya 8 Google Business Profiles yang lengkap dan hours tidak konsisten. Search visibility lokal dan call/direction dapat terpengaruh; perbaikan memerlukan location data owner dan operational process.",
["<b>Audit locations.</b> Daftar store/branch, ownership, verified profile, NAP, category, service, and hours.","<b>Optimize profiles.</b> Isi accurate information, photos, attributes, services, links, and update governance.","<b>Manage reviews.</b> Set response guidelines, escalation, and policy-safe review request process.","<b>Build local pages.</b> Buat unique, useful landing content with location service evidence and proper internal links."],
"Buat local search audit untuk lima lokasi: profile completeness, NAP, category, reviews, local landing pages, citations, owner, and maintenance SLA.",[["Apa itu NAP consistency?","NAP consistency berarti nama bisnis, alamat, dan nomor telepon akurat serta konsisten di direktori dan sumber lokal yang relevan."],["Mengapa review tidak boleh dibeli?","Review palsu atau diberi insentif dapat melanggar platform policies, menyesatkan konsumen, dan merusak kepercayaan terhadap brand."],["Apa tantangan multi-location SEO?","Risikonya meliputi halaman lokasi tipis atau duplikat, data bisnis tidak konsisten, ownership listing, dan governance respons review."]],[["Google Business Profile","Profil bisnis resmi untuk local presence di Google."],["NAP","NAP berarti Name, Address, Phone; ketiganya harus akurat dan konsisten pada listing bisnis lokal yang relevan."],["Citation","Penyebutan informasi bisnis pada directory/listing."],["Local landing page","Halaman yang menjelaskan layanan dan informasi relevan per lokasi."]],"DPA-T11-CH07"),
G("Search Console dan analytics menghubungkan organic visibility dengan behavior dan business outcomes. GSC memberi performance queries/pages, indexing, sitemap, enhancements, and search appearance; GA4 memberi sessions/events/conversions. Metrics memiliki scope dan attribution berbeda; clicks GSC tidak sama dengan sessions GA4. Reporting harus memisahkan branded/non-branded, page type, country/device, and search feature.",
"SIMULATED — GSC clicks naik 20%, tetapi GA4 organic sessions tetap. Investigasi menemukan redirect/consent/tag issue atau perubahan search click-to-session behavior. Analyst harus membandingkan query/page/date/device sebelum menyimpulkan SEO traffic tidak berkualitas.",
["<b>Set reporting scope.</b> Definisikan date range, property, country/device, query/page, brand/non-brand, and page type.","<b>Reconcile metrics.</b> Bandingkan impressions/clicks/CTR/position with sessions/engagement/conversions; jelaskan differences.","<b>Diagnose changes.</b> Cek indexing, page releases, SERP, seasonality, competitor, cannibalization, and tracking.","<b>Recommend roadmap.</b> Prioritaskan by impact, confidence, effort, dependency, and expected business outcome."],
"Buat organic reporting dashboard dan monthly memo dari synthetic/demo data: query, page, clicks, impressions, CTR, position, indexation, sessions, conversions, and prioritized actions.",[["Mengapa GSC clicks tidak sama dengan GA4 sessions?","Click tidak selalu menjadi session akibat loading, redirects, consent, browser, and measurement differences."],["Mengapa average position perlu segmentasi?","Aggregation across queries/pages/devices can hide changes in query mix and SERP features."],["Apa isi SEO recommendation yang actionable?","Rekomendasi harus menyebut halaman atau perubahan teknis spesifik, evidence, impact hypothesis, priority, owner, timeline, serta cara mengukur hasil."]],
[["Search Console","Tool untuk melihat Google Search performance/indexation data."],["CTR","Click-through rate = clicks / impressions."],["Branded query","Query yang menyebut nama brand/product."],["Index coverage","Status URL dalam index/search eligibility."]],"DPA-T11-CH08"),
G("AEO/GEO/AI Search mengamati bagaimana brand/content ditemukan dan dirujuk pada answer engines dan AI features. Fondasi website tetap crawlability, helpful content, entity clarity, source authority, and structured information. Tidak ada markup khusus yang menjamin citation/rank di semua AI systems. Monitoring harus mencatat platform, prompt, date, answer, cited sources, brand mention, and context; hasil sampling tidak boleh disajikan sebagai universal visibility metric.",
"SIMULATED — brand muncul pada dua dari sepuluh prompt category dalam satu LLM. Itu menunjukkan sampel observasi, bukan market-wide share of voice. Audit sumber yang dikutip, content gaps, entity accuracy, and brand proof.",
["<b>Define queries/prompts.</b> Kelompokkan intent, category question, comparison, recommendation, and local queries.","<b>Establish baseline.</b> Catat platform/model, prompt, date, answer, sources/citations, brand presence, and context.","<b>Review source readiness.</b> Periksa crawlable pages, facts, citations, expert authorship, structured data, and consistency.","<b>Run repeatable monitoring.</b> Gunakan prompt set dan sampling schedule yang konsisten; label methodological limits."],
"Buat AI search visibility log dengan 20 prompts lintas informational/commercial/local intents. Catat date, engine, answer, citations, mention/context, source quality, and content actions.",[["Apakah schema menjamin brand muncul di AI answer?","Tidak. Structured data membantu machine understanding di konteks tertentu; tidak menjamin answer inclusion/citation."],["Mengapa prompt sampling bukan market share?","Hasil prompt sampling bergantung model, date, location, wording, personalization, dan response variance; sampel itu tidak mewakili pangsa pasar."],["Apa fondasi AEO/GEO yang tetap relevan?","Accessible, helpful, accurate content, clear entities, authoritative evidence, and sound technical SEO."]],
[["AEO","Answer Engine Optimization, optimasi agar informasi mudah dipahami/digunakan answer systems."],["GEO","Generative Engine Optimization, istilah untuk visibility dalam generative search."],["Citation","Sumber yang dirujuk/dikutip sistem jawaban."],["Entity","Entitas nyata seperti brand, product, person, location, atau organization."]],"DPA-T11-CH09"),
G("SEO Capstone menyatukan audit teknis, keyword/topic research, content strategy, digital PR, local, reporting, and AI visibility baseline menjadi roadmap yang diprioritaskan. Rekomendasi harus mempertimbangkan engineering/content resources dan business impact. Hindari menjanjikan ranking atau traffic uplift tanpa data; nyatakan uncertainty dan measurement plan.",
"SIMULATED — ecommerce 500 URLs punya indexing issue, content duplication, slow category pages, and weak product descriptions. Capstone menyusun 90-day roadmap berdasarkan affected pages, revenue importance, engineering effort, and risk.",
["<b>Audit baseline.</b> Crawl website, GSC/GA4, indexation, templates, content, links, and local/AI context.","<b>Prioritize roadmap.</b> Score issues by impact, confidence, effort, dependencies, and affected pages.","<b>Define workstreams.</b> Technical, content/on-page, authority/PR, local, and measurement owners.","<b>Measure and govern.</b> Set KPIs, baselines, release QA, update cadence, and realistic outcomes."],
"Siapkan SEO capstone: technical audit, keyword/topic map, on-page brief, backlink/PR review, local checklist, Search Console baseline, AI visibility log, prioritized 90-day roadmap, and executive summary.",
[["Mengapa SEO roadmap perlu owner dan dependency?","Banyak fixes butuh engineering, design, content, legal, and product; tanpa owners/dependencies, rekomendasi tidak bisa dieksekusi."],["Apa yang tidak boleh dijanjikan SEO specialist?","Posisi/ranking pasti atau traffic growth tanpa mempertimbangkan competition, indexing, update, and external factors."],["Apa yang membuktikan capstone berbasis evidence?","Source URLs, crawl export, GSC/GA4 data, issue examples, priority rationale, assumptions, and measurement plan."]],[["Technical audit","Pemeriksaan akses, indexation, rendering, performance, and structured technical health."],["Content gap","Kebutuhan informasi/query yang belum dilayani dengan baik."],["Roadmap","Urutan perubahan, owner, effort, timeline, and success criteria."],["SERP","SERP adalah Search Engine Results Page, yaitu halaman hasil yang ditampilkan mesin pencari untuk sebuah query."]],"DPA-T11-CH10")
],
crm:[
G("CRM adalah strategi pengelolaan hubungan customer berbasis data dan lifecycle, bukan sekadar software atau daftar kontak. Lifecycle dapat mencakup lead, onboarding, activation, repeat, loyalty, lapse, and win-back; definisi harus mengikuti model bisnis. CRM specialist menyelaraskan acquisition, sales, service, and customer value dengan consent, data quality, governance, and communication experience.",
"SIMULATED — brand subscription mendapat 10.000 leads, tetapi 60% tidak pernah diaktifkan. Masalah mungkin onboarding, qualification, product usage, or sales follow-up. CRM harus mengidentifikasi lifecycle barrier sebelum menambah blast email.",
["<b>Map lifecycle.</b> Definisikan stage, entry/exit criteria, owner, and customer action.","<b>Align business model.</b> Bedakan B2C/B2B, one-off/subscription, lead/sales, service, and repeat economics.","<b>Set CRM objective.</b> Activation, time-to-value, repeat, retention, reactivation, churn prevention, or loyalty.","<b>Govern channel/data.</b> Tetapkan consent, preference, suppression, data owner, and SLA."],
"Buat CRM lifecycle blueprint untuk satu business model: stage definitions, entry/exit criteria, trigger, owner, business metric, contact policy, and high-risk customer scenarios.",
[["Mengapa CRM bukan sekadar software?","CRM adalah pendekatan untuk mengelola hubungan dan nilai customer sepanjang lifecycle, bukan sekadar aplikasi penyimpan kontak. Software menjalankan workflow; strategi menentukan stage, pengalaman, data, ownership, komunikasi dan ukuran keberhasilan sesuai model bisnis, dengan owner serta definisi yang jelas."],["Apa risiko lifecycle stage tidak memiliki entry/exit criteria?","Entry dan exit criteria menentukan kapan contact memenuhi syarat masuk, berpindah atau keluar dari lifecycle stage. Tanpa definisi, contact dapat menerima pesan yang tidak relevan, masuk ulang secara tidak sengaja atau tertahan di journey setelah goal tercapai."],["Mengapa retention metric harus mengikuti model bisnis?","Retention harus mengikuti pola pembelian dan hubungan bisnis. Subscription dapat mengukur renewal, retail mengukur repeat purchase dalam cadence kategori, durable goods memakai service atau accessory engagement, sedangkan B2B dapat memakai account renewal dan qualified expansion; satu definisi tidak cocok untuk semua."]],
[["Lifecycle","Tahap hubungan customer dengan organisasi."],["Activation","Momen ketika customer mencapai first meaningful value/action."],["Churn","Customer berhenti atau tidak lagi aktif menurut definisi bisnis."],["CRM","Customer Relationship Management; strategi dan sistem pengelolaan relasi customer."]],"DPA-T12-CH01"),
G("Customer data architecture mengatur struktur, identifiers, sources, events, fields, relationships, deduplication, consent, and access. Data dapat berasal dari web/app, POS, CRM, support, email, WhatsApp, sales, and offline systems. Identity resolution harus dilakukan dengan governance dan tidak menggabungkan data hanya karena nama/email mirip. Data model perlu menyebut customer, account, contact, event, transaction, product, and consent entities.",
"SIMULATED — satu customer memiliki email berbeda untuk transaksi marketplace dan website. Deduping berdasarkan nama dapat menggabungkan dua orang; perlu deterministic identifiers, confidence rules, and manual review threshold.",
["<b>Inventory data sources.</b> Dokumentasikan owner, refresh, identifier, fields, consent, and quality.","<b>Design data model.</b> Gambar entities, primary keys, relationships, events, and transaction/customer grain.","<b>Define identity rules.</b> Bedakan deterministic/probabilistic match, duplicates, merge/split, and unknowns.","<b>Apply privacy governance.</b> Tentukan purpose, permissions, retention, deletion, and audit access."],
"Buat CRM data dictionary dan ERD sederhana: contact, account, transaction, product, event, consent, and communication preference. Sertakan dedupe, identity, access, and retention rules.",
[["Mengapa data merge harus memiliki confidence rules?","False merge menggabungkan dua orang atau account berbeda sehingga riwayat transaksi, preference, consent dan komunikasi dapat tertukar. Gunakan identifier yang memiliki tingkat keyakinan sesuai, aturan survivorship, manual review untuk ambiguous matches serta audit trail sebelum menggabungkan record."],["Apa beda contact record dan transaction record?","Contact record menyimpan identitas dan atribut individu atau account sesuai data model. Transaction record mencatat kejadian bisnis seperti order, payment atau return dengan waktu, item, nilai dan status. Relasi keduanya perlu key yang stabil agar aktivitas tidak disamakan dengan profil."],["Apa peran consent dan preference fields?","Consent dan preference fields merekam tujuan, dasar pemrosesan, channel, kategori pesan, status, waktu, sumber dan perubahan pilihan customer. Pisahkan izin marketing dari data kontak atau kebutuhan transaksi, batasi penggunaan sesuai tujuan dan hormati penarikan persetujuan."]],[["Identity resolution","Pengaitan record ke identitas customer dengan rule tertentu."],["Primary key","Primary key adalah identifier unik yang membedakan setiap record atau entity dalam sebuah tabel atau database."],["Data deduplication","Data deduplication mengidentifikasi dan menangani record duplikat agar jumlah contact, event, atau transaksi tidak terhitung ganda."],["Data retention","Aturan berapa lama data disimpan."]],"DPA-T12-CH02"),
G("Segmentation mengelompokkan customer untuk action yang relevan; lead scoring menilai fit/intent/progression; lifecycle stage memberi konteks hubungan. Segment harus memiliki criteria yang reproducible, refresh cadence, size, and owner. RFM (recency, frequency, monetary) berguna untuk transaksi, tetapi tidak menggantikan behavioral/need segmentation. Lead scoring harus divalidasi terhadap sales outcomes agar tidak hanya memberi poin pada aktivitas mudah.",
"SIMULATED — 1.000 leads mendapat skor tinggi karena membuka email berkali-kali, tetapi tak ada yang fit dengan ICP. Model scoring yang baik memasukkan fit, high-intent activity, exclusions, and sales feedback.",
["<b>Define use case.</b> Tentukan tindakan yang ingin didorong dan keputusan siapa yang menggunakan segment.","<b>Set rules.</b> Pilih attributes/events/windows, thresholds, exclusions, and refresh logic.","<b>Validate score.</b> Bandingkan high/low score dengan qualified pipeline, conversion, and false positives.","<b>Operationalize.</b> Tentukan owner, routing, SLA, suppression, and monitoring."],
"Buat segment taxonomy 6 kelompok dan lead score model dengan firmographic/behavioral signals, point weights, exclusions, validation sample, and sales handoff SLA.",[["Apa risiko lead scoring hanya dari email opens?","Email open tracking dapat terpicu oleh image preloading atau privacy protection, bukan tindakan membaca yang dapat dipastikan. Gunakan open hanya sebagai sinyal terbatas; validasi lead dengan fit, explicit actions, qualified engagement, sales acceptance dan outcome downstream."],["Apa beda fit dan intent?","Fit mengukur kecocokan lead dengan target profile, seperti industri, ukuran, kebutuhan dan eligibility. Intent mengukur sinyal kebutuhan atau kesiapan bertindak, misalnya permintaan demo atau pencarian informasi. Skor sebaiknya memisahkan kedua dimensi dan memvalidasi hubungannya dengan sales outcome."],["Bagaimana memvalidasi model scoring?","Validasi scoring dengan membandingkan skor terhadap qualified rate, sales acceptance, conversion dan waktu menuju outcome pada periode berikutnya. Periksa false positives, false negatives, calibration antar-segmen, data leakage dan drift; sesuaikan bobot hanya setelah hasil serta keterbatasan dicatat."]],[["RFM","RFM adalah model segmentasi customer berdasarkan Recency, Frequency, dan Monetary value dari transaksi selama periode tertentu."],["Lead scoring","Model penilaian fit/intent/progression untuk prioritas."],["ICP","Ideal Customer Profile menggambarkan karakteristik account atau customer yang paling sesuai dengan target bisnis."],["False positive","Record yang dianggap eligible/high score tetapi tidak sesuai outcome."]],"DPA-T12-CH03"),
G("Trigger-based communication terjadi karena event/kondisi: signup, purchase, product usage, cart abandon, renewal, inactivity, or service status. Trigger berbeda dari broadcast campaign dan journey sequence. Setiap workflow perlu eligibility, consent, branch, delay, frequency cap, suppression, exit condition, retry, and exception handling. Timing harus masuk akal dengan product use and customer context.",
"SIMULATED — reminder abandoned cart dikirim setelah customer menyelesaikan order lewat marketplace. Tanpa purchase suppression/cross-channel event, customer menerima pesan yang tidak relevan.",
["<b>Map trigger events.</b> Definisikan event source, conditions, parameters, delay, and event quality.","<b>Design branches.</b> Tentukan if/else, consent, segment, action, suppression, and exit.","<b>Set frequency/priority.</b> Tangani competing journeys, quiet hours, service-vs-promo, and priority hierarchy.","<b>Test exception paths.</b> Uji duplicates, retries, missing fields, opt-out, purchase, and delivery failure."],
"Buat workflow diagram untuk welcome, cart abandon, post-purchase, and reactivation. Sertakan trigger/condition/action, branches, delays, suppression, exit, frequency cap, and QA scenarios.",[["Apa beda trigger dan campaign blast?","Trigger workflow berjalan ketika event atau kondisi tertentu terpenuhi, seperti signup, purchase atau renewal. Campaign blast dikirim ke segment pada jadwal yang ditetapkan. Trigger lebih kontekstual, tetapi keduanya tetap memerlukan eligibility, consent, suppression, frequency control dan exit rules."],["Mengapa cross-channel purchase suppression penting?","Cross-channel suppression menyelaraskan status purchase dan opt-out di email, WhatsApp, SMS, push serta paid audiences. Setelah customer membeli atau tidak lagi eligible, journey yang relevan harus berhenti atau berubah agar tidak mengirim reminder, offer maupun pesan yang bertentangan."],["Apa fungsi exit condition?","Exit condition menghentikan atau mengeluarkan contact ketika goal tercapai, eligibility hilang, consent ditarik, customer membeli atau status bisnis berubah. Definisikan event, evaluasi, timing dan owner; pastikan exit berlaku lintas journey terkait, bukan hanya satu workflow."]],[["Trigger","Trigger adalah event atau kondisi yang memulai automation workflow atau mengaktifkan langkah komunikasi tertentu."],["Branch","Branch adalah jalur workflow yang dipilih berdasarkan condition, attribute, atau behaviour contact."],["Suppression","Pengecualian contact dari komunikasi tertentu."],["Exit condition","Exit condition adalah aturan yang menghentikan contact dari journey ketika goal, eligibility, atau consent state berubah."]],"DPA-T12-CH04"),
G("Email, WhatsApp, SMS, and push memiliki permission, format, cost, immediacy, content, and response expectations berbeda. Channel selection harus mengikuti customer preference, urgency, service vs marketing purpose, and local policy/platform terms. Email memerlukan sender/domain, authentication (SPF/DKIM/DMARC), list hygiene, unsubscribe, deliverability; WhatsApp business messaging memiliki template/session/pricing/policy rules yang harus diverifikasi terkini. Jangan menganggap nomor telepon berarti izin marketing.",
"SIMULATED — order delay memerlukan service update segera, sedangkan promo cross-sell dapat menunggu email preference. Mengirim promo WhatsApp kepada contact tanpa consent dapat merusak trust dan melanggar policy.",
["<b>Choose channel by message.</b> Cocokkan urgency, complexity, preference, reach, accessibility, and cost.","<b>Set permission.</b> Catat source/purpose/time of consent, opt-in/opt-out, and preference.","<b>Design content.</b> Susun sender, subject/preview, message body, CTA, template, links, and fallback.","<b>Validate compliance.</b> Check quiet hours, template category, unsubscribe, frequency, policy, and local legal advice."],
"Buat channel decision matrix dan 3 sample communications untuk service update, onboarding, and promotional reactivation. Sertakan consent, preference, opt-out, fallback, and compliance check.",[["Mengapa kepemilikan contact detail belum cukup untuk mengirim marketing?","Memiliki email atau nomor telepon hanya menyediakan alamat kontak, bukan otomatis dasar pemrosesan atau bukti subscription marketing. Tentukan dasar hukum yang relevan menurut UU PDP, jelaskan tujuan penggunaan, simpan status pilihan dan hormati opt-out."],["Kapan SMS/WhatsApp lebih tepat daripada email?","SMS atau WhatsApp dapat sesuai untuk pesan yang cepat dan kontekstual; email cocok untuk informasi lebih panjang atau yang mudah dicari kembali. Pilih berdasarkan urgensi, preference, biaya, permission, template policy, deliverability serta tujuan service atau marketing."],["Mengapa channel fallback perlu dirancang?","Fallback menjaga pesan penting tetap dapat disampaikan ketika channel utama gagal, tetapi tidak boleh menjadi jalan memintas preference atau consent. Tetapkan channel alternatif yang diizinkan, prioritas, suppression bersama, retry limit, biaya dan aturan berhenti setelah berhasil."]],
[["Deliverability","Kemampuan pesan mencapai inbox/device sesuai rules provider."],["Opt-out","Pilihan customer untuk berhenti menerima komunikasi."],["Transactional message","Pesan terkait transaksi/service; tetap harus sesuai legal/policy."],["Template message","Format pesan yang perlu approval/eligibility pada platform tertentu."]],"DPA-T12-CH05"),
G("Automation architecture menyusun trigger, condition, action, branch, delay, data input, integration, retry, and monitoring. Workflow harus idempotent agar event duplicate tidak memicu pesan ganda. API/webhook, CRM, email service, spreadsheet, and data warehouse perlu error handling and ownership. Automation bukan sekadar happy path; desain juga failure, consent change, missing data, and human handoff.",
"SIMULATED — webhook purchase dikirim dua kali sehingga customer menerima dua welcome journeys. Unique event ID, deduplication, idempotency, and journey exit rules mencegah duplicate trigger.",
["<b>Draw architecture.</b> Map source, trigger, transformation, destination, logs, and owner.","<b>Define reliability.</b> Gunakan unique IDs, idempotency, retries, rate limits, and dead-letter/error handling.","<b>Protect data.</b> Validate field mapping, permissions, secrets, minimization, and audit logs.","<b>Test all paths.</b> Jalankan success, duplicate, missing field, API failure, opt-out, and manual escalation tests."],
"Buat automation architecture dan QA plan untuk form-to-CRM-to-email flow. Dokumentasikan schema, API/webhook, dedupe, retries, consent, error queue, monitoring, and human handoff.",[["Apa arti idempotent workflow?","Workflow idempotent menghasilkan state akhir yang sama ketika event identik diproses ulang, tanpa membuat contact, order atau message duplicate. Gunakan stable event/idempotency key, deduplication store dan atomic state transition; jangan menganggap seluruh API action otomatis idempotent."],["Mengapa retry harus memiliki batas?","Retry tanpa batas dapat menggandakan pesan atau tindakan, membebani API dan menciptakan retry storm. Batasi attempts serta total time, gunakan exponential backoff dengan jitter untuk transient errors, dan retry hanya ketika operasi aman atau memiliki idempotency protection."],["Apa yang wajib disimpan dalam error log?","Error log perlu mencatat timestamp, correlation/event ID, contact/workflow ID yang aman, step, error class, response code, retry count, idempotency key, owner dan remediation status. Hindari menyimpan isi data personal yang tidak diperlukan; batasi akses serta retensi log."]],
[["Webhook","Pesan/event yang dikirim antar sistem saat event terjadi."],["Idempotency","Sifat proses agar pengulangan input tidak menggandakan efek."],["Dead-letter queue","Tempat menyimpan event yang gagal diproses setelah retries."],["API","Interface untuk pertukaran data antar aplikasi."]],"DPA-T12-CH06"),
G("Personalization harus memberi relevansi tanpa terasa mengawasi. Gunakan attributes/behavior yang diperlukan, jelaskan value, jaga data minimization, and provide preference controls. Deliverability dipengaruhi sender reputation, authentication (SPF/DKIM/DMARC), list quality, bounce, complaint, engagement, content, and sending behavior. Open rates memiliki privacy limitations; gunakan click, conversion, deliverability, and downstream outcomes secara seimbang.",
"SIMULATED — email personalisasi menyebut lokasi presisi yang tidak pernah diberitahu user dan membuat mereka tidak nyaman. Gunakan context yang transparan, minimal, dan bermanfaat, bukan personalization yang invasif.",
["<b>Choose data fields.</b> Gunakan data yang relevan, lawful, current, and necessary untuk customer value.","<b>Build fallback.</b> Sediakan default content saat attribute missing/outdated; jangan kirim blank or incorrect merge fields.","<b>Check deliverability.</b> Periksa authentication, bounce, complaint, list hygiene, content, and engagement.","<b>Review privacy/trust.</b> Test data use, access, preference, suppression, and customer expectation."],
"Buat personalization map dan email deliverability audit: data fields, source, use/purpose, fallback, preference, SPF/DKIM/DMARC checklist, bounce/complaint, and KPI.",
[["Mengapa open rate tidak selalu reliable?","Open rate dipengaruhi image proxy, preloading dan fitur privasi, sehingga bukan pengukuran attention yang sempurna. Gunakan open hanya sebagai diagnostic terbatas; evaluasi deliverability, click, conversion, unsubscribe, complaint dan downstream value sesuai objective. dengan owner dan definisi yang jelas"],["Apa fungsi SPF, DKIM, dan DMARC?","SPF mengidentifikasi server yang diizinkan mengirim untuk domain; DKIM menandatangani pesan; DMARC menerapkan kebijakan dan alignment terhadap domain From. Gmail meminta SPF atau DKIM bagi semua sender dan SPF, DKIM serta DMARC bagi bulk senders yang mengirim lebih dari 5.000 pesan per hari ke Gmail."],["Bagaimana membuat personalization terasa relevan?","Personalization terasa relevan ketika memakai atribut yang diperlukan untuk tujuan yang dijelaskan, sesuai preference dan harapan customer. Hindari inferensi sensitif atau kejutan invasif; sediakan kontrol, fallback non-personalized, freshness rule dan cara memperbarui atau menarik pilihan."]],
[["Personalization","Penyesuaian experience/message berdasarkan data yang relevan."],["SPF","Sender Policy Framework untuk otorisasi sending hosts."],["DKIM","DomainKeys Identified Mail untuk signature pesan."],["DMARC","Policy/reporting layer untuk domain authentication alignment."]],"DPA-T12-CH07"),
G("Retention, churn, cohort, and LTV mengukur kualitas hubungan customer sepanjang waktu. Cohort dibentuk berdasarkan event awal yang sama; retention perlu definisi activity yang sesuai model bisnis. Churn dapat berupa inactivity, cancellation, lapse, or loss of revenue. LTV harus memperhatikan margin, repeat cadence, refunds, discounts, service cost, and horizon; jangan menghitung revenue-only LTV lalu membandingkannya dengan CAC seolah-olah contribution.",
"SIMULATED — dua customer memiliki revenue LTV sama, tetapi satu membeli produk bermargin rendah dengan biaya support tinggi. CRM investment tidak boleh menganggap keduanya bernilai sama.",
["<b>Define retention/churn.</b> Tetapkan activity event, observation window, inactivity rule, and segment.","<b>Build cohorts.</b> Kelompokkan berdasarkan first purchase/signup/activation and track subsequent periods.","<b>Estimate LTV.</b> Gunakan contribution margin, purchase frequency, lifespan, churn, returns, and service costs.","<b>Design interventions.</b> Kaitkan risk signal dengan relevant communication, service action, and holdout."],
"Buat cohort retention workbook, churn definition, LTV sensitivity model, and 3 intervention hypotheses. Gunakan synthetic transactions and explicitly label assumptions.",[["Mengapa cohort harus memiliki start event yang sama?","Cohort harus memakai inclusion event dan periode awal yang konsisten, misalnya first purchase atau signup, serta return event yang didefinisikan. Ini menyamakan lifecycle age saat membandingkan retention; cohort berdasarkan event berbeda tidak boleh diperlakukan setara tanpa penyesuaian."],["Apa risiko LTV berbasis revenue?","Revenue-only LTV mengabaikan biaya variabel, cost of goods, returns, discount, fulfillment, service dan biaya mempertahankan customer. Untuk keputusan investasi, gunakan contribution atau margin yang disetujui finance, nyatakan horizon, churn/retention assumptions dan sensitivity; jangan menyamakan gross revenue dengan value."],["Apa yang dimaksud churn signal?","Churn signal adalah perubahan perilaku yang berhubungan dengan kemungkinan berhenti atau tidak membeli lagi, seperti penurunan usage, renewal risk atau lapse. Validasi signal terhadap historical outcomes dan segmen; sinyal bukan kepastian churn dan tidak boleh langsung memicu pesan invasif."]],
[["Cohort","Kelompok customer dengan titik awal/event sama."],["Retention rate","Proporsi cohort yang tetap aktif menurut definisi/window."],["Churn rate","Proporsi customer yang berhenti menurut definisi/window."],["Contribution LTV","Nilai customer berdasarkan contribution, bukan revenue saja."]],"DPA-T12-CH08"),
G("Lifecycle experimentation menguji pesan, timing, channel, offer, onboarding sequence, and frequency. Metric seperti delivery, bounce, click, conversion, repeat, complaint, unsubscribe, and revenue harus dipilih sesuai objective. Test perlu randomization unit, holdout, primary KPI, guardrails, sample/duration, and decision rules. CRM lift sering dipengaruhi seasonality, overlapping campaigns, and contact eligibility; holdout membantu menilai incrementality.",
"SIMULATED — subject line A menaikkan opens, tetapi purchases tidak berubah dan unsubscribe meningkat. Jika tujuan revenue/retention, open-rate winner belum tentu bisnis winner.",
["<b>Frame hypothesis.</b> Tentukan stage, barrier, message/timing change, expected mechanism, and outcome.","<b>Design control.</b> Pilih user/contact-level randomization, holdout, sample, duration, and exclusion rules.","<b>Track quality.</b> Monitor primary metric with guardrails for complaints, unsubscribes, margin, and service contacts.","<b>Interpret outcome.</b> Pisahkan short-term engagement from incremental sales/retention."],
"Buat test backlog untuk onboarding, replenishment, win-back: hypothesis, audience, treatment/control, primary/guardrails, timing, sample assumptions, and decision rules.",[["Mengapa opens bukan satu-satunya success metric?","Open adalah proxy engagement dan dapat terdistorsi oleh privacy mechanisms; ia tidak membuktikan perhatian, klik atau nilai bisnis. Evaluasi delivery, click, qualified action, conversion, repeat, margin, unsubscribe dan complaint sesuai objective, sambil menyatakan keterbatasan open tracking."],["Apa fungsi holdout group?","Holdout menahan sebagian eligible audience dari treatment sehingga hasil kelompok yang menerima komunikasi dapat dibandingkan dengan counterfactual yang relevan. Tetapkan randomization unit, exclusion, contamination control, primary metric, guardrail dan periode; perbedaan observed belum otomatis valid bila desain gagal."],["Mengapa frequency perlu guardrail?","Frequency guardrail membatasi paparan per contact dan periode untuk mengurangi fatigue, unsubscribe, complaint serta pengalaman buruk. Tetapkan cap per channel dan lintas journey, suppression hierarchy, exception untuk service messages dan monitoring dampak; satu cap global belum tentu cocok untuk semua pesan."]],[["Holdout","Kelompok yang tidak menerima treatment untuk comparison."],["Frequency cap","Frequency cap membatasi jumlah pesan atau exposure yang boleh diterima customer dalam periode tertentu."],["Control group","Control group adalah kelompok pembanding yang tidak menerima treatment untuk mengestimasi dampak komunikasi secara lebih kredibel."],["Lifecycle metric","Metrik sesuai tahap hubungan customer."]],"DPA-T12-CH09"),
G("CRM Capstone menunjukkan lifecycle system yang menghubungkan data architecture, segments, consent, triggers, channel, automation, deliverability, measurement, and business value. Workflow harus memiliki happy path dan failure path. Data synthetic/demo harus diberi label dan privacy risks ditulis eksplisit. Presentasi harus memperlihatkan bagaimana CRM mengurangi friction atau meningkatkan customer value, bukan sekadar memperbanyak message volume.",
"SIMULATED — subscription brand membangun new subscriber onboarding, usage education, renewal reminder, failed-payment recovery, and churn prevention. Capstone menguji event integrity, suppression, customer support handoff, and cohort impact.",
["<b>Frame lifecycle problem.</b> Tentukan stage, value, churn risk, and objective.","<b>Design data and segments.</b> Bangun schema, consent, segment logic, and trigger rules.","<b>Implement workflow blueprint.</b> Map channel, messages, branches, failures, retries, and QA.","<b>Measure and govern.</b> Buat cohort, holdout, KPI/guardrails, owner, and improvement roadmap."],
"Bangun portfolio pack: lifecycle map, data dictionary/ERD, segment model, consent matrix, workflow diagrams, message samples, QA cases, deliverability audit, cohort/LTV workbook, and executive readout.",
[["Apa bukti CRM system siap dijalankan?","Kesiapan CRM dibuktikan oleh data dictionary dan ownership, consent/preference controls, identity dan deduplication rules, entry/exit serta suppression, tested workflows, deliverability, monitoring, incident response, access control dan rollback. Keberhasilan login atau send test saja tidak membuktikan operasi aman dan terukur."],["Bagaimana membedakan CRM activity dan business impact?","Message volume, sends dan delivery adalah activity metrics yang menggambarkan output operasional. Business impact perlu dinilai melalui activation, qualified conversion, repeat, margin, retention atau incremental lift terhadap pembanding. Laporkan keduanya terpisah agar volume komunikasi tidak disalahartikan sebagai customer value."],["Apa yang harus dilakukan bila opt-out tidak masuk ke automation?","Segera hentikan atau suppress promotional sends untuk record yang opt-out-nya gagal masuk automation. Perbaiki event/pipeline, audit seluruh contact yang terdampak, kirim remedial update hanya sesuai dasar yang berlaku, catat incident dan bukti, lalu uji end-to-end sebelum mengaktifkan ulang."]],[["Lifecycle architecture","Rangkaian stage, data, trigger, channel, and experience."],["Contact policy","Contact policy mengatur eligibility, frequency, channel preferences, suppression, dan aturan komunikasi kepada setiap customer."],["CRM capstone","Portfolio case yang membuktikan data-to-lifecycle execution."],["Governance","Aturan ownership, permissions, quality, and accountability."]],"DPA-T12-CH10")
]
};
Object.assign(ROLE_STUDY_GUIDES, ROLE_STUDY_GUIDES_PART2);
